from itertools import product
import heapq


def _dependency_solver(data, order, maximize):
    packages = data["packages"]
    names = sorted(packages, reverse=(order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    options = []
    for name in names:
        rows = [r for r in packages[name]
                if r["version"] not in blocked.get(name, [])
                and (name not in pins or r["version"] == pins[name])]
        options.append([None] + rows)

    best = None
    best_vector = None
    for choices in product(*options):
        selected = {name: row for name, row in zip(names, choices) if row is not None}
        versions = {name: row["version"] for name, row in selected.items()}
        valid = True
        for name, bounds in data["roots"].items():
            v = versions.get(name)
            if v is None or not bounds[0] <= v <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        edges = {}
        for name, row in selected.items():
            edges[name] = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                v = versions.get(target)
                if v is None or not dep["min"] <= v <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            if name not in edges:
                valid = False
                break
            stack.extend(edges[name])
        if not valid or reachable != set(selected):
            continue

        done, active = set(), set()
        def acyclic(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            if any(not acyclic(child) for child in edges[name]):
                return False
            active.remove(name)
            done.add(name)
            return True
        if not all(acyclic(name) for name in edges):
            continue

        vector = tuple(versions.get(name, -1) for name in names)
        if best is None or (vector > best_vector if maximize else vector < best_vector):
            best, best_vector = versions, vector
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _build_component_01():
    return lambda data: _dependency_solver(data, "ascending", False)


def _build_component_02():
    return lambda data: _dependency_solver(data, "descending", True)


def _build_component_03():
    return lambda data: _dependency_solver(data, "descending", False)


def _build_component_04():
