def _build_component_06():
    def rounded(n, mode):
        return (n + 5000) // 10000 if mode == "half_up" else n // 10000

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            key_id = event.get("id", "anonymous:" + str(pos))
            rank = (sequence, event.get("revision", 0), pos)
            if key_id not in winners or rank > winners[key_id][0]:
                winners[key_id] = (rank, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), mode)
            tax = rounded(net * event.get("tax_bp", 0), mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_ids = None
        best_value = None
        n = len(jobs)
        for mask in range(1 << n):
            chosen = [jobs[i] for i in range(n) if mask >> i & 1]
            if len(chosen) != k:
                continue
            ids = {j["id"] for j in chosen}
            if ids & blocked or not mandatory <= ids:
                continue
            counts = {}
            for job in chosen:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            if any(counts.get(group, 0) > k for group in counts):
                continue
            intervals = sorted((j["start"], j["end"]) for j in chosen)
            if any(intervals[i][0] < intervals[i - 1][1]
                   for i in range(1, len(intervals))):
                continue
            ids_list = sorted(ids)
            value = sum(j["value"] for j in chosen)
            if (best_ids is None or value > best_value
                    or (value == best_value and ids_list < best_ids)):
                best_ids, best_value = ids_list, value
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_08():
    def solve(data):
        n = data["n"]
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source, target = data["source"], data["target"]
        start = data["start"]
        initial_mask = bit.get(source, 0)
        initial = (source, initial_mask, data["coupons"])
        dist = {initial: start}
        queue = [(start, source, initial_mask, data["coupons"])]
        graph = [[] for _ in range(n)]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            time, node, mask, left = heapq.heappop(queue)
            state = (node, mask, left)
            if dist.get(state) != time:
                continue
            if node == target and mask == full and left == 0:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                for spent in (0, 1) if left else (0,):
                    duration = edge["duration"]
                    if spent:
                        duration = max(2, duration - edge.get("discount", 0))
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    new_mask = mask | bit.get(nxt, 0)
                    new_left = left - spent
                    new_state = (nxt, new_mask, new_left)
                    if arrival < dist.get(new_state, float("inf")):
                        dist[new_state] = arrival
                        heapq.heappush(queue, (arrival, nxt, new_mask, new_left))
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _build_component_01(),
    "component_02": _build_component_02(),
    "component_03": _build_component_03(),
    "component_04": _build_component_04(),
    "component_05": _build_component_05(),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
